// Close is to release resource of ConnPool, it is executed when client is closed.
func (p *connPool) Close() error {
	p.conns.Range(func(addr, trans interface{}) bool {
		p.conns.Delete(addr)
		trans.(*transports).close()
		return true
	})
	return nil
}

// Dump prints the connection pool status for debugging.
func (p *connPool) Dump() interface{} {
	var poolInfo = make(map[string]interface{})
	poolInfo["size"] = p.size
	poolInfo["remoteService"] = p.remoteService

	conns := make(map[string]interface{})
	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)
		connInfo := make(map[string]interface{})
		connInfo["size"] = trans.size
		connInfo["index"] = atomic.LoadUint32(&trans.index)
		connInfo["activeTransports"] = len(trans.cliTransports)
		conns[addr] = connInfo
		return true
	})
	poolInfo["connections"] = conns

	return poolInfo
}

// newTLSConn constructs a client-side TLS connection and performs handshake.

