// String prints human readable information.
func (tp Protocol) String() string {
	if tp == 0 {
		return "PurePayload"
	}

	// Check for known individual flags first
	switch tp {
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	}

	// For composites, iterate bits and build pipe-separated string
	// Flags ordered by bit value (ascending)
	var parts []string
	flags := []struct {
		val  Protocol
		name string
	}{
		{TTHeader, "TTHeader"},               // 2
		{Framed, "Framed"},                   // 4
		{HTTP, "HTTP"},                       // 8
		{GRPC, "GRPC"},                       // 16
		{HESSIAN2, "Hessian2"},               // 32
		{TTHeaderStreaming, "TTHeaderStreaming"}, // 64
		{GRPCStreaming, "GRPCStreaming"},     // 128
	}

	for _, f := range flags {
		if tp&f.val != 0 {
			parts = append(parts, f.name)
		}
	}

	if len(parts) > 0 {
		return strings.Join(parts, "|")
	}
	return Unknown
}

