func main() {
	// Test individual flags
	fmt.Printf("PurePayload: %s\n", transport.PurePayload.String())
	fmt.Printf("TTHeader: %s\n", transport.TTHeader.String())
	fmt.Printf("Framed: %s\n", transport.Framed.String())
	fmt.Printf("GRPC: %s\n", transport.GRPC.String())
	fmt.Printf("TTHeaderStreaming: %s\n", transport.TTHeaderStreaming.String())
	fmt.Printf("GRPCStreaming: %s\n", transport.GRPCStreaming.String())

	// Test known composite
	fmt.Printf("TTHeaderFramed: %s\n", transport.TTHeaderFramed.String())

	// Test arbitrary composites (GRPC | Framed should output "Framed|GRPC")
	composite1 := transport.GRPC | transport.Framed
	fmt.Printf("GRPC|Framed: %s\n", composite1.String())

	// Test (TTHeader | HTTP)
	composite2 := transport.TTHeader | transport.HTTP
	fmt.Printf("TTHeader|HTTP: %s\n", composite2.String())

	// Test three-way composite
	composite3 := transport.TTHeader | transport.Framed | transport.HTTP
	fmt.Printf("TTHeader|Framed|HTTP: %s\n", composite3.String())
}
